// src/pages/customer/Dashboard.jsx

import React from 'react';
// สมมติว่ามี Component Card ที่ Import มาจาก src/components/Card.jsx
// สมมติว่ามี Component Button ที่ Import มาจาก src/components/Button.jsx
// สมมติว่ามี Component Icon ที่ Import มาจาก src/components/Icon.jsx
import Card from '../../components/Card';
import Icon from '../../components/Icon'; 
// *** หมายเหตุ: คุณต้องสร้างไฟล์ Card.jsx และ Icon.jsx ใน src/components/ ก่อน

const mockClaims = [
  { id: 101, license: 'กข 1234', status: 'รอเลือกอู่ซ่อม', urgent: false, date: '2025-10-25' },
  { id: 102, license: 'งจ 5678', status: 'กำลังซ่อม', urgent: true, date: '2025-10-20' },
];

const Dashboard = () => {
  const currentClaim = mockClaims.find(c => c.status !== 'ซ่อมเสร็จสิ้น');
  const pendingActions = [
    { title: 'เลือกอู่ซ่อมรถ', description: 'กรุณาเลือกอู่ที่ต้องการซ่อมเพื่อดำเนินการต่อ', link: '/customer/select-garage' },
    { title: 'ใบเคลม 102: อนุมัติซ่อมด่วน', description: 'รอการตอบรับจากบริษัทประกัน', link: '/customer/urgent-request' },
  ].filter(item => item.title === (currentClaim?.status === 'รอเลือกอู่ซ่อม' ? 'เลือกอู่ซ่อมรถ' : (currentClaim?.urgent ? 'ใบเคลม 102: อนุมัติซ่อมด่วน' : null)));

  return (
    <div className="space-y-8 animate-in">
      {/* Welcome Header */}
      <div className="p-6 bg-primary-100 rounded-card">
        <h1 className="text-3xl font-thai font-semibold text-primary-700">
          สวัสดีคุณลูกค้า A, ยินดีต้อนรับกลับสู่ ClaimMate
        </h1>
        <p className="text-primary-600 mt-2 font-thai">
          "แจ้งไว เคลมง่าย อุ่นใจทุกการชน"
        </p>
      </div>

      {/* Quick Status / Priority Alert */}
      {currentClaim ? (
        <Card className="border-l-4 border-primary-500 p-4">
          <h2 className="text-xl font-thai font-semibold text-primary-dark flex items-center">
            <Icon name="tracking" className="w-6 h-6 mr-3 text-primary-500" />
            สถานะเคลมล่าสุด: #{currentClaim.id} (ทะเบียน {currentClaim.license})
          </h2>
          <p className="mt-2 text-3xl font-en font-bold text-error-800">
            {currentClaim.status}
            {currentClaim.urgent && (
                <span className="ml-3 inline-block bg-error text-white text-xs font-bold px-2 py-1 rounded-full uppercase">
                    ซ่อมด่วน
                </span>
            )}
          </p>
          <div className="mt-4 flex space-x-4">
            <a href={`/customer/claims/${currentClaim.id}`} className="bg-primary-500 hover:bg-primary-600 text-white font-semibold py-2 px-4 rounded-button transition-colors">
              ดูรายละเอียดทั้งหมด
            </a>
          </div>
        </Card>
      ) : (
        <Card>
          <h2 className="text-xl font-thai font-semibold">ไม่มีรายการเคลมที่ดำเนินการอยู่</h2>
          <p className="mt-2 text-neutral-600 font-thai">
            หากคุณมีการแจ้งเคลมทางโทรศัพท์แล้ว แต่ไม่เห็นรายการ กรุณารอเจ้าหน้าที่อัปโหลดเอกสาร หรือติดต่อบริษัทประกัน
          </p>
        </Card>
      )}

      {/* Pending Actions Section (สิ่งที่ต้องทำ) */}
      <h2 className="text-2xl font-thai font-semibold text-neutral-dark">รายการที่คุณต้องดำเนินการ</h2>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {pendingActions.length > 0 ? (
          pendingActions.map((action, index) => (
            <Card key={index} className="bg-warning-50 border-l-4 border-warning">
              <h3 className="text-lg font-thai font-semibold text-warning-800 flex items-center">
                <Icon name="urgent" className="w-5 h-5 mr-2 text-warning-700" />
                {action.title}
              </h3>
              <p className="text-neutral-600 mt-2">{action.description}</p>
              <a href={action.link} className="mt-4 inline-block text-primary-500 hover:text-primary-700 underline font-semibold">
                ดำเนินการ
              </a>
            </Card>
          ))
        ) : (
          <Card>
            <p className="text-neutral-500 font-thai">ไม่มีรายการที่ต้องดำเนินการในขณะนี้ ทุกอย่างเรียบร้อยดี!</p>
          </Card>
        )}
      </div>

    </div>
  );
};

export default Dashboard;
